function sections(body){
 const lines=(body||"").split(/\r?\n/), out=[];
 let take=0;
 for(let i=0;i<lines.length;i++){
   const l=lines[i];
   if(/^#{1,4}\s+/.test(l) && /(problem|scope|accept|status|remaining|expected|decision|gap|current|done|close|non-goal|deliverable|implementation|outcome)/i.test(l)){out.push(l);take=12;continue;}
   if(take>0){if(/^#{1,4}\s+/.test(l)){take=0;} else {out.push(l);take--;}}
 }
 return out.join("\n").slice(0,5000);
}
